package com.example.riskplatform.service;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.example.riskplatform.common.BusinessException;import com.example.riskplatform.dto.Requests.CompanyRequest;import com.example.riskplatform.entity.Company;import com.example.riskplatform.mapper.CompanyMapper;import lombok.RequiredArgsConstructor;import com.example.riskplatform.service.rag.CorpusEvents;import org.springframework.beans.BeanUtils;import org.springframework.stereotype.Service;import java.util.*;
@Service @RequiredArgsConstructor public class CompanyService{private final CompanyMapper mapper;private final DataScopeService scope;private final AuditService audit;private final CorpusEvents corpus;public List<Company>list(String k){LambdaQueryWrapper<Company>w=new LambdaQueryWrapper<>();if(k!=null&&!k.isBlank())w.and(x->x.like(Company::getCompanyName,k).or().like(Company::getCompanyCode,k));List<Long>ids=scope.allowedCompanyIds();if(ids!=null){if(ids.isEmpty())return List.of();w.in(Company::getId,ids);}return mapper.selectList(w.orderByDesc(Company::getId));}public Company get(Long id){if(!scope.canAccess(id))throw new BusinessException(403,"无权访问该企业");Company c=mapper.selectById(id);if(c==null)throw new BusinessException("企业不存在");return c;}public Company create(CompanyRequest r){Company c=new Company();BeanUtils.copyProperties(r,c);mapper.insert(c);corpus.upsert("company",c.getId(),c.getId());audit.log("CREATE","COMPANY",c.getId(),c.getCompanyName());return c;}public Company update(Long id,CompanyRequest r){get(id);Company c=new Company();BeanUtils.copyProperties(r,c);c.setId(id);mapper.updateById(c);corpus.upsert("company",id,id);audit.log("UPDATE","COMPANY",id,r.getCompanyName());return mapper.selectById(id);}public void delete(Long id){get(id);mapper.deleteById(id);corpus.remove("company",id,id);audit.log("DELETE","COMPANY",id,"delete");}}
